// Arma el email de una alerta: valida destinatario/entidad, resuelve variables
// y renderiza la plantilla. Nunca lanza error: devuelve { ok: false, reason }
// para que el flujo registre un alert_actions FAILED y siga con la siguiente.
const crypto = require('crypto');
const ctx = $input.first().json || {};
const trigger = $('When Called by Alert Scheduler').first().json;

const fail = (reason) => [{
  json: { ok: false, reason, alert_instance_id: trigger.alert_instance_id ?? null },
}];

if (!ctx.alert_instance_id) {
  return fail(`Alerta no encontrada (alert_instance_id=${trigger.alert_instance_id ?? 'null'})`);
}
// Una alerta recibe un solo email automático, aunque el sub-flujo se vuelva a
// ejecutar (re-ejecución manual en n8n, scheduler disparado dos veces).
if (ctx.already_sent) {
  return fail('Esta alerta ya tiene un email enviado; no se reenvía');
}
if (['IGNORED', 'SUPPRESSED', 'SNOOZED'].includes(ctx.alert_status)) {
  return fail(`La alerta está en estado ${ctx.alert_status}; no se envía email`);
}

const tpl = ctx.template;
if (!tpl) {
  return fail(`No hay communication_templates EMAIL activo para email_template_id=${trigger.email_template_id ?? 'null'}`);
}

const patient = ctx.patient;
if (!patient) {
  return fail(`Paciente no encontrado para patient_id=${trigger.patient_id ?? 'null'}`);
}
if (!patient.is_active || !patient.is_patient) {
  return fail(`${patient.name || patient.id} no es un paciente activo; no se envía email`);
}

// --- Destinatario: email del paciente o, si es dependiente, el del responsable.
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const emailProblem = (email, bounced) => {
  if (!email) return 'vacío';
  if (!EMAIL_RE.test(email)) return `inválido (${email})`;
  if (bounced) return `rebotado (${email})`;
  return null;
};

let to = null;
let recipientName = patient.name || '';
let toResponsible = false;
let recipientPref = null;

const patientProblem = emailProblem(patient.email, patient.email_bounced);
if (!patientProblem) {
  to = patient.email;
  recipientPref = patient.pref_enabled;
} else if (patient.is_dependant && !emailProblem(patient.responsible_email, patient.responsible_email_bounced)) {
  to = patient.responsible_email;
  recipientName = patient.responsible_name || recipientName;
  toResponsible = true;
  recipientPref = patient.responsible_pref_enabled;
}

if (!to) {
  const responsiblePart = patient.is_dependant
    ? `; responsable: ${patient.responsible_name ? emailProblem(patient.responsible_email, patient.responsible_email_bounced) : 'sin responsable'}`
    : '';
  return fail(`Paciente sin email válido: ${patientProblem}${responsiblePart} (patient_id=${patient.id})`);
}

// --- Preferencias. La configuración global de la clínica (canal email por
// categoría) siempre se respeta. La preferencia del paciente se ignora por
// defecto en el auto-envío; una regla puede volver a respetarla con
// condition_config.respect_user_preferences = true.
if (!ctx.channel_enabled) {
  return fail(`El canal email está deshabilitado para la categoría "${ctx.category_slug ?? 'sin categoría'}"`);
}
const userPrefOverridden = recipientPref === false;
if (userPrefOverridden && ctx.respect_user_preferences) {
  return fail(`${recipientName} desactivó los emails de "${ctx.category_slug}"`);
}

// --- Modo prueba (system_configurations): solo se envía a la lista blanca.
if (String(ctx.test_mode_enabled).toLowerCase() === 'true') {
  const whitelist = String(ctx.test_whitelist || '')
    .split(',')
    .map((e) => e.trim().toLowerCase())
    .filter(Boolean);
  if (!whitelist.includes(String(to).toLowerCase())) {
    return fail(`Modo prueba de email activo: ${to} no está en alert_email_test_whitelist`);
  }
}

// --- Formatos (Uruguay). Las fechas llegan como YYYY-MM-DD de pared, sin zona.
const longDate = (iso) => {
  if (!iso) return '';
  const d = new Date(`${iso}T12:00:00Z`);
  if (isNaN(d.getTime())) return iso;
  return d.toLocaleDateString('es-UY', {
    weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC',
  });
};
const CURRENCY_SYMBOL = { UYU: '$', USD: 'US$', EUR: '€', ARS: 'AR$', BRL: 'R$' };
const money = (amount, currency) => {
  const n = Number(amount);
  const num = isNaN(n)
    ? String(amount ?? '')
    : n.toLocaleString('es-UY', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const symbol = CURRENCY_SYMBOL[currency] || currency || '';
  return `${symbol} ${num}`.trim();
};

// --- Variables (mismo vocabulario que las plantillas de email del frontend).
const clinic = ctx.clinic || {};
let webhookBase = '';
try {
  webhookBase = String($env.WEBHOOK_URL || '').replace(/\/+$/, '');
} catch (e) {
  webhookBase = '';
}
const logoUrl = webhookBase ? `${webhookBase}/webhook/clinic/logo` : '';

const vars = {
  patient_name: patient.name || '',
  recipient_name: recipientName,
  // Vacios si el email va al propio paciente; con el nombre si va al responsable:
  // "la proxima cita{{for_patient}}" / "feliz cumpleaños{{to_patient}}".
  for_patient: toResponsible ? ` de ${patient.name}` : '',
  to_patient: toResponsible ? ` a ${patient.name}` : '',
  clinic_name: clinic.name || '',
  clinic_address: clinic.address || '',
  clinic_phone: clinic.phone || '',
  clinic_email: clinic.email || '',
  clinic_logo: logoUrl,
  // Para botones "Llamar a la clínica": vacío si no hay teléfono (el botón se quita).
  clinic_phone_link: String(clinic.phone || '').replace(/[^\d+]/g, '')
    ? `tel:${String(clinic.phone).replace(/[^\d+]/g, '')}`
    : '',
  clinic_contact: [clinic.phone, clinic.email].filter(Boolean).join(' · '),
};

const ACTIVE_APPOINTMENT_STATUSES = ['scheduled', 'confirmed', 'pending'];

// Botones Confirmar/Cancelar (flujo "Appointment Email Action (noauth)").
// Un token aleatorio por email, válido para las dos acciones; a la base va solo
// su sha256 (nodo "Store Action Token"). Sin URL pública de n8n o con la cita
// ya fuera de plazo, las variables quedan vacías y los botones se quitan.
let actionToken = null;

switch (ctx.reference_table) {
  case 'appointments': {
    const appt = ctx.appointment;
    if (!appt) {
      return fail(`Cita no encontrada o no asociada al paciente para reference_id=${ctx.reference_id}`);
    }
    if (!ACTIVE_APPOINTMENT_STATUSES.includes(appt.status)) {
      return fail(`La cita ${appt.id} está en estado "${appt.status}"; no se envía recordatorio`);
    }
    vars.appointment_date = longDate(appt.date_iso);
    vars.appointment_time = appt.time || '';
    vars.doctor_name = appt.doctor_name || 'Profesional a confirmar';
    vars.location = [appt.sede_name, appt.sede_address].filter(Boolean).join(' — ') || clinic.address || '';
    vars.confirm_url = '';
    vars.cancel_url = '';
    if (webhookBase && appt.actions_open && appt.actions_expire_at) {
      const clear = crypto.randomBytes(32).toString('base64url');
      actionToken = {
        appointment_id: appt.id,
        hash: crypto.createHash('sha256').update(clear).digest('hex'),
        expires_at: appt.actions_expire_at,
      };
      const actionUrl = (a) => `${webhookBase}/webhook/appointments/email-action_noauth?t=${clear}&a=${a}`;
      // Una cita ya confirmada solo muestra "Cancelar".
      if (appt.status !== 'confirmed') vars.confirm_url = actionUrl('confirm');
      vars.cancel_url = actionUrl('cancel');
    }
    break;
  }
  case 'invoices': {
    const inv = ctx.invoice;
    if (!inv) {
      return fail(`Factura no encontrada o no asociada al paciente para reference_id=${ctx.reference_id}`);
    }
    if (!inv.is_collectible || !(Number(inv.effective_residual) > 0)) {
      return fail(`La factura ${inv.doc_no || inv.id} ya no tiene saldo pendiente`);
    }
    vars.invoice_doc_no = inv.doc_no || String(inv.id);
    vars.invoice_amount = money(inv.effective_residual, inv.currency);
    vars.invoice_due_date = longDate(inv.due_date_iso);
    vars.invoice_currency = inv.currency || '';
    // Alias usados por las plantillas de factura del frontend.
    vars.doc_no = vars.invoice_doc_no;
    vars.currency = vars.invoice_currency;
    break;
  }
  case 'users':
    break;
  default:
    return fail(`reference_table no soportada para email automático: ${ctx.reference_table}`);
}

// --- Render: {{token}} simple. Un token desconocido aborta el envío para no
// mandarle "{{algo}}" literal al paciente.
const escapeHtml = (s) => String(s ?? '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const unknown = new Set();
const render = (text, asHtml) => String(text || '').replace(
  /\{\{\s*([a-zA-Z0-9_.]+)\s*\}\}/g,
  (match, key) => {
    if (!(key in vars)) {
      unknown.add(key);
      return match;
    }
    return asHtml ? escapeHtml(vars[key]) : String(vars[key]);
  },
);

const subject = render(tpl.subject, false).trim();
const rawBody = tpl.body_html || tpl.body_text || '';
const isHtml = /<[a-z][\s\S]*>/i.test(rawBody);
// Las plantillas por defecto del frontend ya traen el layout completo
// (contenedor de 600px con cabecera y pie); esas se envian tal cual.
const hasLayout = /<html|max-width\s*:/i.test(rawBody);

// Layout con los colores del sistema: cabecera índigo (--nav-bg #1e1b4b) con
// línea de acento violeta (--brand-mid), contenido en blanco con borde
// --border y pie en gris lila. Tablas + estilos inline para clientes de correo.
const FONT = "'Plus Jakarta Sans',Arial,Helvetica,sans-serif";
const logoCell = vars.clinic_logo
  ? `<td style="width:1%;padding-right:14px;vertical-align:middle;"><img src="{{clinic_logo}}" alt="" height="40" style="display:block;height:40px;width:auto;max-width:110px;border-radius:8px;background:#ffffff;" /></td>`
  : '';
const shell = (inner) => `<div style="margin:0;padding:24px 12px;background:#f2f0f5;font-family:${FONT};">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:0 auto;border-collapse:separate;background:#ffffff;border:1px solid #e4e0eb;border-radius:16px;overflow:hidden;">
  <tr><td style="background:#1e1b4b;padding:20px 28px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;"><tr>
      ${logoCell}
      <td style="vertical-align:middle;">
        <div style="font-size:16px;font-weight:700;line-height:1.3;color:#ffffff;">{{clinic_name}}</div>
        <div style="font-size:12px;line-height:1.4;color:#c7c3e6;">{{clinic_address}}</div>
      </td>
    </tr></table>
  </td></tr>
  <tr><td style="height:3px;line-height:3px;font-size:0;background:#7a3fd9;">&nbsp;</td></tr>
  <tr><td style="padding:28px;font-family:${FONT};font-size:14px;line-height:1.6;color:#0c0520;">${inner}</td></tr>
  <tr><td style="padding:16px 28px;background:#faf9fc;border-top:1px solid #efedf3;text-align:center;font-family:${FONT};font-size:11px;line-height:1.6;color:#6d6d78;">
    <div style="font-weight:600;color:#3b3654;">{{clinic_name}}</div>
    <div>{{clinic_contact}}</div>
    <div style="margin-top:6px;color:#9a97a8;">Mensaje automático. Podés responder este email para comunicarte con la clínica.</div>
  </td></tr>
</table>
</div>`;

// Texto plano: se escapa y se respetan los saltos de linea. HTML sin layout:
// se usa el contenido tal cual. En ambos casos se envuelve en el layout.
let html;
if (hasLayout) {
  html = render(rawBody, true);
} else {
  const inner = isHtml ? render(rawBody, true) : render(rawBody, true).replace(/\r?\n/g, '<br>');
  html = render(shell(inner), true);
}

if (unknown.size > 0) {
  return fail(`La plantilla ${tpl.code} usa variables desconocidas: ${[...unknown].join(', ')}. Disponibles: ${Object.keys(vars).join(', ')}`);
}
if (!subject) {
  return fail(`La plantilla ${tpl.code} no tiene asunto`);
}

// Sin logo resuelto, se quita la imagen para que no aparezca rota; sin
// telefono/email, se quitan los botones que apuntarian a un enlace vacio.
html = html
  .replace(/<img\b[^>]*\bsrc=(["'])\s*\1[^>]*>/gi, '')
  .replace(/<a\b[^>]*\bhref=(["'])\s*\1[^>]*>[\s\S]*?<\/a>/gi, '')
  .replace(/<p\b[^>]*>\s*<\/p>/gi, '');

return [{
  json: {
    ok: true,
    alert_instance_id: ctx.alert_instance_id,
    to,
    to_responsible: toResponsible,
    user_pref_overridden: userPrefOverridden,
    recipient_name: recipientName,
    subject,
    html,
    template_code: tpl.code,
    sender_name: clinic.name || '',
    reply_to: clinic.email || '',
    // Solo si la plantilla usa los botones: un token que no viaja en el email no se guarda.
    action_token: actionToken && /\{\{\s*(confirm_url|cancel_url)\s*\}\}/.test(`${tpl.subject || ''}${rawBody}`)
      ? actionToken
      : null,
  },
}];

const built = $('Build Email').first().json;
const res = $input.first().json || {};

if (res.id && !res.error) {
  return [{ json: { ...built, ok: true, gmail_message_id: res.id, gmail_thread_id: res.threadId || null } }];
}

const err = res.error?.message || (typeof res.error === 'string' ? res.error : null) || res.message || JSON.stringify(res);
return [{ json: { ok: false, reason: `Gmail rechazó el envío a ${built.to}: ${err}` } }];

const sent = $('Check Gmail Response').first().json;
const t = $('When Called by Alert Scheduler').first().json;
return [{ json: { success: true, channel: 'email', alert_instance_id: t.alert_instance_id || null, to: sent.to, gmail_message_id: sent.gmail_message_id || null } }];

const t = $('When Called by Alert Scheduler').first().json;
const src = $input.first() ? $input.first().json : {};
return [{ json: { success: false, channel: 'email', alert_instance_id: t.alert_instance_id || null, reason: src.result_message || 'Fallo en el auto-envío de email' } }];

// Si el email lleva botones y el token no se guardó, no se envía: el paciente
// recibiría enlaces que no funcionan. Queda como fallo en alert_actions.
const built = $('Build Email').first().json;
if (!built.action_token) return [{ json: built }];

const res = $input.first().json || {};
if (res.id) return [{ json: built }];

const err = res.error?.message || (typeof res.error === 'string' ? res.error : null) || res.message || 'sin fila insertada';
return [{ json: { ok: false, reason: `No se pudo guardar el token de los botones Confirmar/Cancelar: ${err}` } }];
